-- Khởi tạo cấu trúc cho schema hoàn toàn trống. Không chạy V001 sau bước khởi tạo này.
-- Được tạo từ thông tin ánh xạ entity đã rà soát; không thêm dữ liệu nghiệp vụ ban đầu.

DO $$ BEGIN IF EXISTS (SELECT 1 FROM pg_tables WHERE schemaname=current_schema()) THEN RAISE EXCEPTION 'Baseline requires an empty schema; use the existing-schema initialization path instead.'; END IF; END $$;

create table ai_recommendations (score float(53) not null, generated_at timestamp(6) not null, id bigint generated by default as identity, room_id bigint not null, user_id bigint not null, model_version varchar(30), primary key (id));
create table amenities (active boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, version bigint not null, code varchar(255) not null, icon varchar(255), name varchar(255) not null unique, primary key (id));
create table analytics_refresh_state (data_version bigint not null, property_id bigint not null, refreshed_at timestamp(6) with time zone not null, source_cutoff_at timestamp(6) with time zone, primary key (property_id));
create table audit_logs (actor_id bigint, created_at timestamp(6) with time zone not null, entity_id bigint not null, id bigint generated by default as identity, occurred_at timestamp(6) with time zone not null, event_id uuid not null, action varchar(255) not null, actor_type varchar(255) not null check ((actor_type in ('USER','SYSTEM','PROVIDER'))), correlation_id varchar(255) not null, entity_type varchar(255) not null, from_status varchar(255), outcome varchar(255) not null check ((outcome in ('ATTEMPT','SUCCESS','FAILURE'))), reason TEXT, request_id varchar(255) not null, to_status varchar(255), after_state jsonb, before_state jsonb, primary key (id), constraint uq_audit_logs_0 unique (event_id));
create table bank_webhook_events (attempt_count integer not null, verified boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, lease_until timestamp(6) with time zone, next_attempt_at timestamp(6) with time zone, payment_id bigint, processed_at timestamp(6) with time zone, provider_occurred_at timestamp(6) with time zone, received_at timestamp(6) with time zone not null, refund_id bigint, event_id varchar(255) not null, event_type varchar(255) not null check ((event_type in ('PAYMENT_SUCCEEDED','PAYMENT_FAILED','REFUND_SUCCEEDED','REFUND_FAILED'))), last_error TEXT, lease_owner varchar(255), merchant_id varchar(255) not null, payload_hash varchar(255) not null, processing_status varchar(255) not null check ((processing_status in ('RECEIVED','PROCESSING','PROCESSED','RETRY','REJECTED','NEEDS_ATTENTION'))), provider varchar(255) not null check ((provider in ('FAKE_BANK'))), provider_reference varchar(255) not null, payload jsonb, primary key (id), constraint uq_bank_webhook_events_0 unique (provider, merchant_id, event_id));
create table booking_nights (fee_amount numeric(19,2) not null, nightly_rate numeric(19,2) not null, stay_date date not null, tax_amount numeric(19,2) not null, booking_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, price_version bigint not null, currency varchar(255) not null, primary key (id), unique (booking_id, stay_date));
create table booking_status_history (actor_id bigint, booking_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, occurred_at timestamp(6) with time zone not null, event_id uuid not null, actor_type varchar(255) not null check ((actor_type in ('USER','SYSTEM','PROVIDER'))), correlation_id varchar(255) not null, from_status varchar(255) check ((from_status in ('HOLD','PENDING_PAYMENT','CONFIRMED','CHECKED_IN','COMPLETED','CANCELLED','CANCELLATION_PENDING','REFUND_PENDING','REFUNDED','EXPIRED','NEEDS_ATTENTION','NO_SHOW'))), reason TEXT, source varchar(255) not null check ((source in ('CUSTOMER','HOST','SUPPORT','ADMIN','SYSTEM','FAKE_BANK','SCHEDULER','WEBHOOK','RECONCILIATION'))), to_status varchar(255) not null check ((to_status in ('HOLD','PENDING_PAYMENT','CONFIRMED','CHECKED_IN','COMPLETED','CANCELLED','CANCELLATION_PENDING','REFUND_PENDING','REFUNDED','EXPIRED','NEEDS_ATTENTION','NO_SHOW'))), primary key (id), constraint uq_bookingstatushistory_0 unique (event_id));
create table bookings (cancellation_fee numeric(19,2), check_in date not null, check_out date not null, checkin_local_snapshot time(0) not null, fee_amount numeric(19,2) not null, guest_count integer not null, loyalty_discount_percent numeric(5,2), refundable_amount numeric(19,2), subtotal_amount numeric(19,2) not null, tax_amount numeric(19,2) not null, total_amount numeric(19,2) not null, actual_check_in timestamp(6) with time zone, actual_check_out timestamp(6) with time zone, cancelled_at timestamp(6) with time zone, cancelled_by bigint, checked_in_by_id bigint, checked_out_by_id bigint, confirmed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, customer_id bigint not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, price_version bigint not null, property_id bigint not null, room_id bigint not null, room_type_id bigint not null, room_unit_id bigint, updated_at timestamp(6) with time zone not null, version bigint not null, voucher_id bigint, idempotency_key varchar(120), quote_token varchar(120), booking_code varchar(255) not null unique, cancel_reason varchar(255), checkin_verification_method varchar(255), currency varchar(255) not null, guest_segment_snapshot varchar(255) not null check ((guest_segment_snapshot in ('NEW','RETURNING','UNKNOWN'))), property_timezone_snapshot varchar(255) not null, source_channel varchar(255) not null check ((source_channel in ('WEB','MOBILE','ADMIN_ASSISTED','UNKNOWN'))), special_request varchar(255), status varchar(255) not null check ((status in ('HOLD','PENDING_PAYMENT','CONFIRMED','CHECKED_IN','COMPLETED','CANCELLED','CANCELLATION_PENDING','REFUND_PENDING','REFUNDED','EXPIRED','NEEDS_ATTENTION','NO_SHOW'))), cancellation_policy_snapshot jsonb not null, primary key (id));
create table cancellation_policies (active boolean not null, policy_revision integer not null, created_at timestamp(6) with time zone not null, effective_at timestamp(6) with time zone not null, host_id bigint, id bigint generated by default as identity, property_id bigint not null, updated_at timestamp(6) with time zone not null, version bigint not null, name varchar(255) not null, primary key (id), constraint uq_cancellationpolicy_0 unique (property_id, name, policy_revision));
create table cancellation_policy_rules (days_before_checkin integer not null, refund_percent numeric(19,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, policy_id bigint not null, primary key (id), constraint uq_cancellationpolicyrule_0 unique (policy_id, days_before_checkin));
create table checkin_requests (agreed_checkin_at timestamp(6) with time zone, booking_id bigint not null, closed_at timestamp(6) with time zone, conversation_id bigint not null, counter_proposed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, customer_accepted_at timestamp(6) with time zone, id bigint generated by default as identity, origin_message_id bigint not null, proposed_at timestamp(6) with time zone not null, requested_by_id bigint not null, responded_at timestamp(6) with time zone, responded_by_id bigint, updated_at timestamp(6) with time zone not null, version bigint not null, note TEXT, response_note TEXT, status varchar(255) not null check ((status in ('PENDING','COUNTER_PROPOSED','APPROVED','REJECTED','CLOSED','CANCELLED'))), primary key (id), constraint uq_checkin_requests_0 unique (origin_message_id));
create table co_hosts (co_host_user_id bigint not null, created_at timestamp(6) not null, host_id bigint not null, id bigint generated by default as identity, status varchar(255) not null check ((status in ('PENDING','ACTIVE','REVOKED'))), permissions jsonb not null, primary key (id), unique (host_id, co_host_user_id));
create table collection_items (added_at timestamp(6) not null, collection_id bigint not null, id bigint generated by default as identity, room_id bigint not null, primary key (id), unique (collection_id, room_id));
create table collections (is_public boolean not null, created_at timestamp(6) not null, id bigint generated by default as identity, user_id bigint not null, share_token varchar(50) unique, name varchar(150) not null, primary key (id));
create table complaint_tickets (acknowledged_at timestamp(6) with time zone, assigned_support_id bigint, booking_id bigint, closed_at timestamp(6) with time zone, conversation_id bigint not null, created_at timestamp(6) with time zone not null, created_by_id bigint not null, customer_confirmed_at timestamp(6) with time zone, id bigint generated by default as identity, origin_message_id bigint not null, resolved_at timestamp(6) with time zone, resolved_by_id bigint, response_due_at timestamp(6) with time zone not null, updated_at timestamp(6) with time zone not null, version bigint not null, issue_type varchar(255) not null, resolution TEXT, severity varchar(255) not null check ((severity in ('LOW','NORMAL','HIGH','URGENT'))), status varchar(255) not null check ((status in ('OPEN','ACKNOWLEDGED','IN_PROGRESS','RESOLVED','CLOSED'))), primary key (id), constraint uq_complaint_tickets_0 unique (origin_message_id));
create table config_change_logs (actor_id bigint not null, changed_at timestamp(6) with time zone not null, config_value_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, previous_config_value_id bigint, correlation_id varchar(255) not null, new_value TEXT not null, old_value TEXT, reason TEXT not null, primary key (id));
create table config_definitions (definition_version integer not null, max_value numeric(19,2), min_value numeric(19,2), publicly_readable boolean not null, config_key varchar(255) not null, description TEXT not null, value_type varchar(255) not null check ((value_type in ('STRING','INTEGER','DECIMAL','BOOLEAN','DURATION','JSON'))), allowed_scopes jsonb not null, allowed_values jsonb, primary key (config_key));
create table config_values (policy_version integer not null, created_at timestamp(6) with time zone not null, effective_at timestamp(6) with time zone not null, id bigint generated by default as identity, scope_id bigint, updated_at timestamp(6) with time zone not null, updated_by_id bigint not null, version bigint not null, change_reason varchar(255) not null, config_key varchar(255) not null, scope varchar(255) not null check ((scope in ('GLOBAL','TENANT','PROPERTY'))), value_text TEXT not null, value_type varchar(255) not null check ((value_type in ('STRING','INTEGER','DECIMAL','BOOLEAN','DURATION','JSON'))), primary key (id));
create table conversation_participants (assigned_by_id bigint, conversation_id bigint not null, joined_at timestamp(6) with time zone not null, left_at timestamp(6) with time zone, user_id bigint not null, version bigint not null, participant_role varchar(255) not null check ((participant_role in ('CUSTOMER','HOST','SUPPORT'))), primary key (conversation_id, user_id));
create table conversations (booking_id bigint, closed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, customer_id bigint not null, host_id bigint not null, id bigint generated by default as identity, last_message_seq bigint not null, property_id bigint not null, room_id bigint, updated_at timestamp(6) with time zone not null, version bigint not null, status varchar(255) not null check ((status in ('OPEN','CLOSED'))), type varchar(255) not null check ((type in ('INQUIRY','BOOKING_SUPPORT'))), primary key (id));
create table currency_exchange_rates (rate numeric(18,6) not null, base_currency varchar(5) not null, target_currency varchar(5) not null, id bigint generated by default as identity, updated_at timestamp(6) not null, primary key (id), unique (base_currency, target_currency));
create table dispute_evidence (created_at timestamp(6) not null, id bigint generated by default as identity, ticket_id bigint not null, uploaded_by bigint not null, evidence_type varchar(255) not null check ((evidence_type in ('IMAGE','VIDEO','CHAT_LOG'))), url varchar(255) not null, primary key (id));
create table dynamic_pricing_suggestions (applied boolean not null, suggested_price numeric(12,2) not null, target_date date not null, created_at timestamp(6) not null, id bigint generated by default as identity, room_id bigint not null, model_version varchar(30), reason TEXT, primary key (id));
create table email_template_versions (version_no integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, published_at timestamp(6) with time zone, published_by_id bigint, template_id bigint not null, html_body TEXT not null, subject TEXT not null, text_body TEXT not null, allowed_variables jsonb not null, required_variables jsonb not null, primary key (id), constraint uq_email_template_versions_0 unique (template_id, version_no));
create table email_templates (active_version integer, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, version bigint not null, locale varchar(255) not null, status varchar(255) not null check ((status in ('DRAFT','ACTIVE','ARCHIVED'))), template_code varchar(255) not null check ((template_code in ('ACCOUNT_CREATED','EMAIL_VERIFICATION','BOOKING_CONFIRMED','PAYMENT_SUCCEEDED','PAYMENT_FAILED','REFUND_SUCCEEDED','REFUND_FAILED','CHECKIN_REMINDER','COMPLAINT_REPLY','CHECKIN_CONFIRMED'))), primary key (id), constraint uq_email_templates_0 unique (template_code, locale));
create table host_profiles (auto_booking_default boolean not null, is_active boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null unique, display_name varchar(150) not null, business_name varchar(200), bio TEXT, host_status varchar(255) not null check ((host_status in ('PENDING','APPROVED','REJECTED','SUSPENDED'))), primary key (id));
