create table idempotency_records (response_code integer, completed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone, id bigint generated by default as identity, resource_id bigint, actor_key varchar(255) not null, idempotency_key varchar(255) not null, request_hash varchar(255) not null, resource_type varchar(255), scope varchar(255) not null, status varchar(255) not null check ((status in ('IN_PROGRESS','COMPLETED'))), response_body jsonb, primary key (id), unique (scope, idempotency_key));
create table kyc_documents (created_at timestamp(6) not null, id bigint generated by default as identity, reviewed_by bigint, user_id bigint not null, doc_type varchar(50) not null, file_url varchar(255) not null, status varchar(255) not null check ((status in ('PENDING','APPROVED','REJECTED'))), primary key (id));
create table loyalty_ranks (discount_percent numeric(5,2) not null, min_points integer not null, id bigint generated by default as identity, name varchar(30) not null unique check ((name in ('MEMBER','SILVER','GOLD','PLATINUM','DIAMOND'))), benefits jsonb, primary key (id));
create table mail_delivery_attempts (attempt_no integer not null, attempted_at timestamp(6) with time zone not null, completed_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, mail_event_id bigint not null, triggered_by_id bigint, error_code varchar(255), operator_action_key varchar(255), provider_message_id varchar(255), result varchar(255) not null check ((result in ('STARTED','SUCCEEDED','TEMPORARY_FAILURE','PERMANENT_FAILURE','UNKNOWN'))), primary key (id), constraint uq_mail_delivery_attempts_0 unique (mail_event_id, attempt_no));
create table mail_events (retry_count integer not null, created_at timestamp(6) with time zone not null, due_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone, id bigint generated by default as identity, lease_until timestamp(6) with time zone, recipient_id bigint, sent_at timestamp(6) with time zone, template_version_id bigint not null, event_id uuid not null, business_key varchar(255) not null, correlation_id varchar(255) not null, dead_letter_reason TEXT, event_type varchar(255) not null check ((event_type in ('ACCOUNT_CREATED','EMAIL_VERIFICATION','BOOKING_CONFIRMED','PAYMENT_SUCCEEDED','PAYMENT_FAILED','REFUND_SUCCEEDED','REFUND_FAILED','CHECKIN_REMINDER','COMPLAINT_REPLY','CHECKIN_CONFIRMED'))), last_error_code varchar(255), lease_owner varchar(255), recipient_address varchar(255) not null, recipient_identity varchar(255) not null, recipient_masked varchar(255) not null, status varchar(255) not null check ((status in ('QUEUED','SENDING','SENT','RETRY','UNKNOWN','FAILED_VALIDATION','FAILED','DLQ','CANCELLED'))), payload_snapshot jsonb not null, primary key (id), constraint uq_mail_events_0 unique (event_id, event_type, recipient_identity), constraint uq_mail_events_1 unique (event_type, business_key, recipient_identity, template_version_id));
create table media_assets (created_at timestamp(6) with time zone not null, created_by_id bigint not null, deleted_at timestamp(6) with time zone, finalized_at timestamp(6) with time zone, id bigint generated by default as identity, property_id bigint, room_id bigint, size_bytes bigint not null, updated_at timestamp(6) with time zone not null, upload_expires_at timestamp(6) with time zone not null, version bigint not null, checksum_sha256 varchar(255), content_type varchar(255) not null, object_key varchar(255) not null, status varchar(255) not null check ((status in ('PENDING','READY','DELETING','PENDING_EXPIRED','FAILED','DELETED'))), primary key (id), constraint uq_media_assets_0 unique (object_key));
create table messages (conversation_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, media_asset_id bigint, read_at timestamp(6) with time zone, redacted_at timestamp(6) with time zone, redacted_by_id bigint, sender_id bigint not null, seq bigint not null, body TEXT, client_message_id varchar(255) not null, content_type varchar(255) not null check ((content_type in ('TEXT','IMAGE','LOCATION','TEMPLATE'))), correlation_id varchar(255) not null, purpose varchar(255) not null check ((purpose in ('NORMAL','COMPLAINT','CHECKIN_REQUEST'))), redaction_reason varchar(255), request_hash varchar(255) not null, status varchar(255) not null check ((status in ('SENT','REDACTED'))), primary key (id), constraint uq_message_0 unique (conversation_id, seq), constraint uq_message_1 unique (conversation_id, sender_id, client_message_id));
create table notifications (is_read boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, read_at timestamp(6) with time zone, recipient_id bigint not null, resource_id bigint not null, event_id uuid not null, channel varchar(255) not null check ((channel in ('IN_APP','EMAIL','BOTH'))), content TEXT not null, event_type varchar(255) not null, notif_type varchar(255) not null check ((notif_type in ('BOOKING','MESSAGE','RANK_UP','SYSTEM','PROMOTION'))), resource_type varchar(255) not null, title varchar(255) not null, primary key (id), constraint uq_notification_0 unique (event_id, recipient_id));
create table otp_verifications (is_used boolean not null, created_at timestamp(6) not null, expires_at timestamp(6) not null, id bigint generated by default as identity, user_id bigint, otp_code varchar(10) not null, email varchar(150) not null, purpose varchar(255) not null check ((purpose in ('REGISTER','FORGOT_PASSWORD'))), primary key (id));
create table outbox_events (payload_version integer not null, retry_count integer not null, aggregate_id bigint not null, available_at timestamp(6) with time zone not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, lease_until timestamp(6) with time zone, processed_at timestamp(6) with time zone, event_id uuid not null, aggregate_type varchar(255) not null, event_type varchar(255) not null, last_error TEXT, lease_owner varchar(255), status varchar(255) not null check ((status in ('PENDING','PROCESSING','SENT','FAILED','PROCESSED','RETRY','DLQ'))), payload jsonb not null, primary key (id), constraint uq_outboxevent_0 unique (event_id));
create table payments (amount numeric(19,2) not null, captured_amount numeric(19,2) not null, is_open boolean not null, booking_id bigint not null, captured_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, intent_expires_at timestamp(6) with time zone not null, paid_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, version bigint not null, gateway_transaction_ref varchar(100), callback_payload TEXT, correlation_id varchar(255) not null, currency varchar(255) not null, failure_code varchar(255), failure_message TEXT, idempotency_key varchar(255) not null, merchant_id varchar(255) not null, method varchar(255) not null check ((method in ('VNPAY','MOMO','ZALOPAY','CREDIT_CARD','APPLE_PAY','GOOGLE_PAY','FAKE_BANK_DEBIT'))), provider varchar(255) not null check ((provider in ('FAKE_BANK'))), provider_reference varchar(255), request_hash varchar(255) not null, status varchar(255) not null check ((status in ('PENDING','INITIATED','PROCESSING','SUCCESS','SUCCEEDED','FAILED','TIMED_OUT','REFUNDED','NEEDS_ATTENTION','UNKNOWN','RECONCILING'))), primary key (id), constraint uq_payment_0 unique (provider, merchant_id, idempotency_key), constraint uq_payment_1 unique (provider, merchant_id, provider_reference));
create table permissions (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, version bigint not null, code varchar(255) not null unique, description TEXT, name varchar(255) not null, primary key (id));
create table point_history (points_change integer not null, booking_id bigint, created_at timestamp(6) not null, id bigint generated by default as identity, user_id bigint not null, reason TEXT, primary key (id));
create table properties (checkin_local time(0) not null, checkout_local time(0) not null, latitude numeric(19,2), longitude numeric(19,2), cancellation_policy_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, owner_id bigint not null, updated_at timestamp(6) with time zone not null, version bigint not null, address varchar(255) not null, city varchar(255) not null, country varchar(255), description TEXT, name varchar(255) not null, public_contact varchar(255), slug varchar(255) unique, status varchar(255) not null check ((status in ('DRAFT','PUBLISHED','PAUSED','ARCHIVED'))), timezone varchar(255) not null, primary key (id));
create table read_receipts (conversation_id bigint not null, last_read_seq bigint not null, updated_at timestamp(6) with time zone not null, user_id bigint not null, version bigint not null, primary key (conversation_id, user_id));
create table reconciliation_cases (attempt_count integer not null, assigned_to_id bigint, booking_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, next_attempt_at timestamp(6) with time zone, payment_id bigint, refund_id bigint, resolved_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, version bigint not null, case_type varchar(255) not null check ((case_type in ('PAYMENT_UNKNOWN','CAPTURE_WITHOUT_CONFIRMATION','LATE_CAPTURE','REFUND_UNKNOWN','AMOUNT_MISMATCH','UNMATCHED_EVENT'))), operation_key varchar(255) not null, resolution TEXT, status varchar(255) not null check ((status in ('OPEN','PROCESSING','RESOLVED','NEEDS_ATTENTION'))), detail jsonb not null, primary key (id), constraint uq_reconciliation_cases_0 unique (operation_key));
create table refresh_tokens (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, replaced_by bigint, revoked_at timestamp(6) with time zone, user_id bigint not null, family_id uuid not null, device_label varchar(255), token_hash varchar(255) not null, primary key (id), constraint uq_refresh_tokens_0 unique (token_hash), constraint uq_refresh_tokens_1 unique (replaced_by));
create table refund_requests (amount numeric(12,2) not null, currency varchar(5) not null, approved_by bigint, booking_id bigint not null, created_at timestamp(6) not null, id bigint generated by default as identity, payment_id bigint, processed_at timestamp(6), version bigint not null, failure_code varchar(80), idempotency_key varchar(120), provider_reference varchar(120) unique, failure_message TEXT, reason TEXT, refund_destination varchar(255) not null check ((refund_destination in ('WALLET','BANK'))), status varchar(255) not null check ((status in ('PENDING','REQUESTED','APPROVED','PROCESSING','REJECTED','FAILED','TIMED_OUT','PAID','SUCCEEDED','NEEDS_ATTENTION','UNKNOWN','RECONCILING'))), primary key (id));
create table refunds (amount numeric(19,2) not null, attempt_count integer not null, reservation_active boolean not null, booking_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, next_attempt_at timestamp(6) with time zone, payment_id bigint not null, processed_at timestamp(6) with time zone, requested_by_id bigint, updated_at timestamp(6) with time zone not null, version bigint not null, correlation_id varchar(255) not null, currency varchar(255) not null, failure_code varchar(255), failure_message TEXT, idempotency_key varchar(255) not null, merchant_id varchar(255) not null, provider varchar(255) not null check ((provider in ('FAKE_BANK'))), provider_reference varchar(255), reason TEXT not null, refund_code varchar(255) not null, request_hash varchar(255) not null, status varchar(255) not null check ((status in ('PENDING','REQUESTED','APPROVED','PROCESSING','REJECTED','FAILED','TIMED_OUT','PAID','SUCCEEDED','NEEDS_ATTENTION','UNKNOWN','RECONCILING'))), primary key (id), constraint uq_refunds_0 unique (refund_code), constraint uq_refunds_1 unique (payment_id, idempotency_key), constraint uq_refunds_2 unique (provider, merchant_id, provider_reference));
