-- Các ràng buộc trong danh mục sử dụng tính năng riêng của PostgreSQL.


CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE UNIQUE INDEX IF NOT EXISTS uq_users_email_normalized ON users(lower(btrim(email)));

CREATE UNIQUE INDEX IF NOT EXISTS uq_payment_open_booking ON payments(booking_id) WHERE is_open;

CREATE UNIQUE INDEX IF NOT EXISTS uq_room_cover ON room_images(room_id) WHERE cover;

CREATE UNIQUE INDEX IF NOT EXISTS uq_conversation_open_booking ON conversations(booking_id,type) WHERE booking_id IS NOT NULL AND status='OPEN';

CREATE UNIQUE INDEX IF NOT EXISTS uq_checkin_active_booking ON checkin_requests(booking_id) WHERE status IN ('PENDING','COUNTER_PROPOSED','APPROVED');

CREATE UNIQUE INDEX IF NOT EXISTS uq_config_revision ON config_values(config_key,scope,scope_id,policy_version) NULLS NOT DISTINCT;

CREATE UNIQUE INDEX IF NOT EXISTS uq_mail_operator_action ON mail_delivery_attempts(mail_event_id,operator_action_key) WHERE operator_action_key IS NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uq_reminder_sent_window ON scheduled_reminders(booking_id,reminder_type,window_code) WHERE sent_at IS NOT NULL;

ALTER TABLE user_roles ALTER COLUMN assigned_at SET DEFAULT CURRENT_TIMESTAMP;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='users'::regclass AND conname='ck_catalog_users_token_version') THEN ALTER TABLE users ADD CONSTRAINT ck_catalog_users_token_version CHECK (token_version >= 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='properties'::regclass AND conname='ck_catalog_properties_coordinates') THEN ALTER TABLE properties ADD CONSTRAINT ck_catalog_properties_coordinates CHECK ((latitude IS NULL OR latitude BETWEEN -90 AND 90) AND (longitude IS NULL OR longitude BETWEEN -180 AND 180)); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='room_types'::regclass AND conname='ck_catalog_room_types_capacity') THEN ALTER TABLE room_types ADD CONSTRAINT ck_catalog_room_types_capacity CHECK (max_guests > 0 AND (max_adults IS NULL OR max_adults >= 0) AND (max_children IS NULL OR max_children >= 0)); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='cancellation_policies'::regclass AND conname='ck_catalog_cancellation_policies_revision') THEN ALTER TABLE cancellation_policies ADD CONSTRAINT ck_catalog_cancellation_policies_revision CHECK (policy_revision > 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='cancellation_policy_rules'::regclass AND conname='ck_catalog_cancellation_policy_rules_values') THEN ALTER TABLE cancellation_policy_rules ADD CONSTRAINT ck_catalog_cancellation_policy_rules_values CHECK (days_before_checkin >= 0 AND refund_percent BETWEEN 0 AND 100); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='room_rates'::regclass AND conname='ck_catalog_room_rates_money') THEN ALTER TABLE room_rates ADD CONSTRAINT ck_catalog_room_rates_money CHECK (amount >= 0 AND currency='VND' AND price_version >= 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='room_sale_blocks'::regclass AND conname='ck_catalog_room_sale_blocks_dates') THEN ALTER TABLE room_sale_blocks ADD CONSTRAINT ck_catalog_room_sale_blocks_dates CHECK (date_from < date_to); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='media_assets'::regclass AND conname='ck_catalog_media_assets_size') THEN ALTER TABLE media_assets ADD CONSTRAINT ck_catalog_media_assets_size CHECK (size_bytes > 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='media_assets'::regclass AND conname='ck_catalog_media_assets_ready') THEN ALTER TABLE media_assets ADD CONSTRAINT ck_catalog_media_assets_ready CHECK (status <> 'READY' OR finalized_at IS NOT NULL); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='room_images'::regclass AND conname='ck_catalog_room_images_order') THEN ALTER TABLE room_images ADD CONSTRAINT ck_catalog_room_images_order CHECK (sort_order >= 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='bookings'::regclass AND conname='ck_catalog_bookings_dates') THEN ALTER TABLE bookings ADD CONSTRAINT ck_catalog_bookings_dates CHECK (check_in < check_out); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='bookings'::regclass AND conname='ck_catalog_bookings_money') THEN ALTER TABLE bookings ADD CONSTRAINT ck_catalog_bookings_money CHECK (guest_count > 0 AND subtotal_amount >= 0 AND tax_amount >= 0 AND fee_amount >= 0 AND total_amount=subtotal_amount+tax_amount+fee_amount AND currency='VND'); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='booking_nights'::regclass AND conname='ck_catalog_booking_nights_money') THEN ALTER TABLE booking_nights ADD CONSTRAINT ck_catalog_booking_nights_money CHECK (nightly_rate >= 0 AND tax_amount >= 0 AND fee_amount >= 0 AND currency='VND'); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='room_allocations'::regclass AND conname='ck_catalog_room_allocations_range') THEN ALTER TABLE room_allocations ADD CONSTRAINT ck_catalog_room_allocations_range CHECK (NOT isempty(stay) AND NOT lower_inf(stay) AND NOT upper_inf(stay) AND lower_inc(stay) AND NOT upper_inc(stay)); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='room_allocations'::regclass AND conname='ck_catalog_room_allocations_release') THEN ALTER TABLE room_allocations ADD CONSTRAINT ck_catalog_room_allocations_release CHECK ((status='RELEASED')=(released_at IS NOT NULL)); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='payments'::regclass AND conname='ck_catalog_payments_money') THEN ALTER TABLE payments ADD CONSTRAINT ck_catalog_payments_money CHECK (amount > 0 AND captured_amount >= 0 AND captured_amount <= amount AND currency='VND'); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='refunds'::regclass AND conname='ck_catalog_refunds_money') THEN ALTER TABLE refunds ADD CONSTRAINT ck_catalog_refunds_money CHECK (amount > 0 AND currency='VND' AND attempt_count >= 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='refunds'::regclass AND conname='ck_catalog_refunds_reservation') THEN ALTER TABLE refunds ADD CONSTRAINT ck_catalog_refunds_reservation CHECK ((status NOT IN ('SUCCEEDED','FAILED') OR NOT reservation_active) AND (status NOT IN ('REQUESTED','PROCESSING','UNKNOWN','RECONCILING') OR reservation_active)); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='verification_tokens'::regclass AND conname='ck_catalog_verification_tokens_limits') THEN ALTER TABLE verification_tokens ADD CONSTRAINT ck_catalog_verification_tokens_limits CHECK (attempts >= 0 AND expires_at > created_at); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='refresh_tokens'::regclass AND conname='ck_catalog_refresh_tokens_limits') THEN ALTER TABLE refresh_tokens ADD CONSTRAINT ck_catalog_refresh_tokens_limits CHECK (expires_at > created_at AND (replaced_by IS NULL OR replaced_by <> id)); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='reviews'::regclass AND conname='ck_catalog_reviews_rating') THEN ALTER TABLE reviews ADD CONSTRAINT ck_catalog_reviews_rating CHECK (rating BETWEEN 1 AND 5); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='conversations'::regclass AND conname='ck_catalog_conversations_seq') THEN ALTER TABLE conversations ADD CONSTRAINT ck_catalog_conversations_seq CHECK (last_message_seq >= 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='conversation_participants'::regclass AND conname='ck_catalog_conversation_participants_time') THEN ALTER TABLE conversation_participants ADD CONSTRAINT ck_catalog_conversation_participants_time CHECK (left_at IS NULL OR left_at >= joined_at); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='messages'::regclass AND conname='ck_catalog_messages_content') THEN ALTER TABLE messages ADD CONSTRAINT ck_catalog_messages_content CHECK (seq > 0 AND (body IS NOT NULL OR media_asset_id IS NOT NULL)); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='read_receipts'::regclass AND conname='ck_catalog_read_receipts_seq') THEN ALTER TABLE read_receipts ADD CONSTRAINT ck_catalog_read_receipts_seq CHECK (last_read_seq >= 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='complaint_tickets'::regclass AND conname='ck_catalog_complaint_tickets_resolved') THEN ALTER TABLE complaint_tickets ADD CONSTRAINT ck_catalog_complaint_tickets_resolved CHECK (status NOT IN ('RESOLVED','CLOSED') OR resolution IS NOT NULL); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='checkin_requests'::regclass AND conname='ck_catalog_checkin_requests_approved') THEN ALTER TABLE checkin_requests ADD CONSTRAINT ck_catalog_checkin_requests_approved CHECK (status <> 'APPROVED' OR agreed_checkin_at IS NOT NULL); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='config_definitions'::regclass AND conname='ck_catalog_config_definitions_limits') THEN ALTER TABLE config_definitions ADD CONSTRAINT ck_catalog_config_definitions_limits CHECK (definition_version > 0 AND (min_value IS NULL OR max_value IS NULL OR min_value <= max_value)); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='config_values'::regclass AND conname='ck_catalog_config_values_scope') THEN ALTER TABLE config_values ADD CONSTRAINT ck_catalog_config_values_scope CHECK (policy_version > 0 AND ((scope='GLOBAL')=(scope_id IS NULL))); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='email_template_versions'::regclass AND conname='ck_catalog_email_template_versions_version') THEN ALTER TABLE email_template_versions ADD CONSTRAINT ck_catalog_email_template_versions_version CHECK (version_no > 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='mail_events'::regclass AND conname='ck_catalog_mail_events_retry') THEN ALTER TABLE mail_events ADD CONSTRAINT ck_catalog_mail_events_retry CHECK (retry_count >= 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='mail_delivery_attempts'::regclass AND conname='ck_catalog_mail_delivery_attempts_attempt') THEN ALTER TABLE mail_delivery_attempts ADD CONSTRAINT ck_catalog_mail_delivery_attempts_attempt CHECK (attempt_no > 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='scheduled_reminders'::regclass AND conname='ck_catalog_scheduled_reminders_window') THEN ALTER TABLE scheduled_reminders ADD CONSTRAINT ck_catalog_scheduled_reminders_window CHECK (policy_version > 0 AND due_at <= cutoff_at); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='report_exports'::regclass AND conname='ck_catalog_report_exports_rows') THEN ALTER TABLE report_exports ADD CONSTRAINT ck_catalog_report_exports_rows CHECK (row_count IS NULL OR row_count >= 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='analytics_refresh_state'::regclass AND conname='ck_catalog_analytics_refresh_state_version') THEN ALTER TABLE analytics_refresh_state ADD CONSTRAINT ck_catalog_analytics_refresh_state_version CHECK (data_version >= 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='outbox_events'::regclass AND conname='ck_catalog_outbox_events_retry') THEN ALTER TABLE outbox_events ADD CONSTRAINT ck_catalog_outbox_events_retry CHECK (retry_count >= 0 AND payload_version > 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='reconciliation_cases'::regclass AND conname='ck_catalog_reconciliation_cases_attempt') THEN ALTER TABLE reconciliation_cases ADD CONSTRAINT ck_catalog_reconciliation_cases_attempt CHECK (attempt_count >= 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='bank_webhook_events'::regclass AND conname='ck_catalog_bank_webhook_events_attempt') THEN ALTER TABLE bank_webhook_events ADD CONSTRAINT ck_catalog_bank_webhook_events_attempt CHECK (attempt_count >= 0); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='room_allocations'::regclass AND conname='ex_catalog_room_allocation') THEN ALTER TABLE room_allocations ADD CONSTRAINT ex_catalog_room_allocation EXCLUDE USING gist (room_id WITH =, stay WITH &&) WHERE (released_at IS NULL); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='read_receipts'::regclass AND conname='fk_read_receipt_participant') THEN ALTER TABLE read_receipts ADD CONSTRAINT fk_read_receipt_participant FOREIGN KEY (conversation_id,user_id) REFERENCES conversation_participants(conversation_id,user_id); END IF; END $$;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='email_templates'::regclass AND conname='fk_template_active_version') THEN ALTER TABLE email_templates ADD CONSTRAINT fk_template_active_version FOREIGN KEY (id,active_version) REFERENCES email_template_versions(template_id,version_no); END IF; END $$;

CREATE INDEX IF NOT EXISTS ix_outbox_due ON outbox_events(status,available_at);

CREATE INDEX IF NOT EXISTS ix_mail_due ON mail_events(status,due_at);

CREATE INDEX IF NOT EXISTS ix_reminder_due ON scheduled_reminders(status,due_at);

CREATE INDEX IF NOT EXISTS ix_message_cursor ON messages(conversation_id,seq);

CREATE INDEX IF NOT EXISTS ix_audit_resource ON audit_logs(entity_type,entity_id,occurred_at);

CREATE INDEX IF NOT EXISTS ix_funnel_property_time ON user_behavior_logs(property_id,event_time,event_type);
